// Title: C# Unit Test for :root Selector with EnableCssCustomProperties in Aspose.Cells HTML Export
// Description: Demonstrates how to create automated tests that verify the presence or absence of a `:root` CSS block in the HTML generated by Aspose.Cells when the HtmlSaveOptions.EnableCssCustomProperties flag is toggled. The example builds a sample workbook, saves it to a memory stream as HTML, and asserts the correct CSS output.
// Keywords: Aspose.Cells | HtmlSaveOptions | EnableCssCustomProperties | C# | unit test | :root selector | HTML export | CSS custom properties | NUnit | MSTest | xUnit
// Common Searches: Aspose.Cells unit test for :root selector | EnableCssCustomProperties true HTML output | DisableCssCustomProperties HTML without :root | C# test Aspose.Cells HTMLSaveOptions | verify CSS custom properties in Aspose.Cells export
// Developer Intent: Ensure the HTML produced by Aspose.Cells includes a `:root` CSS block only when EnableCssCustomProperties is enabled.
// Use Cases: Add regression tests to CI pipelines that catch changes in CSS custom‑property generation. | Validate theming support by confirming the `:root` block appears when required. | Prevent unwanted CSS output by asserting its absence when the feature is disabled.
// AI Prompts: Generate an MSTest method that checks for a ':root' selector in the HTML output when HtmlSaveOptions.EnableCssCustomProperties is true. | Write an xUnit test that asserts the HTML string does not contain ':root' when EnableCssCustomProperties is false, using Aspose.Cells. | Refactor the console program into a NUnit test class with separate tests for enabled and disabled CSS custom properties, including proper assertions.

using System;
using System.IO;
using System.Text;
using System.Drawing;
using Aspose.Cells;

namespace AsposeCellsTests
{
    // Demonstrates how to create automated tests that verify the presence or absence of a `:root` CSS block in the HTML generated by Aspose.Cells when the HtmlSaveOptions.EnableCssCustomProperties flag is toggled. The example builds a sample workbook, saves it to a memory stream as HTML, and asserts the correct CSS output.
    class Program
    {
        static void Main()
        {
            try
            {
                EnableCssCustomProperties_ShouldContainRootSelector();
                Console.WriteLine("EnableCssCustomProperties test passed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"EnableCssCustomProperties test failed: {ex.Message}");
            }

            try
            {
                DisableCssCustomProperties_ShouldNotContainRootSelector();
                Console.WriteLine("DisableCssCustomProperties test passed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"DisableCssCustomProperties test failed: {ex.Message}");
            }
        }

        // Helper method to generate a simple workbook with some formatted cells
        private static Workbook CreateSampleWorkbook()
        {
            var workbook = new Workbook();
            var sheet = workbook.Worksheets[0];

            // Add sample data
            sheet.Cells["A1"].PutValue("Header");
            sheet.Cells["A2"].PutValue("Value 1");
            sheet.Cells["A3"].PutValue("Value 2");

            // Apply a style to trigger CSS generation
            var style = workbook.CreateStyle();
            style.Font.IsBold = true;
            style.Font.Color = Color.Red;
            sheet.Cells["A1"].SetStyle(style);

            return workbook;
        }

        // Test that enabling CSS custom properties adds a :root selector in the HTML output
        private static void EnableCssCustomProperties_ShouldContainRootSelector()
        {
            // Arrange
            var workbook = CreateSampleWorkbook();
            var options = new HtmlSaveOptions
            {
                EnableCssCustomProperties = true
            };

            // Act
            string htmlContent;
            using (var ms = new MemoryStream())
            {
                workbook.Save(ms, options);
                htmlContent = Encoding.UTF8.GetString(ms.ToArray());
            }

            // Assert
            if (!htmlContent.Contains(":root {"))
            {
                throw new InvalidOperationException("HTML output should contain a ':root' selector when EnableCssCustomProperties is true.");
            }
        }

        // Test that disabling CSS custom properties does not add a :root selector
        private static void DisableCssCustomProperties_ShouldNotContainRootSelector()
        {
            // Arrange
            var workbook = CreateSampleWorkbook();
            var options = new HtmlSaveOptions
            {
                EnableCssCustomProperties = false
            };

            // Act
            string htmlContent;
            using (var ms = new MemoryStream())
            {
                workbook.Save(ms, options);
                htmlContent = Encoding.UTF8.GetString(ms.ToArray());
            }

            // Assert
            if (htmlContent.Contains(":root {"))
            {
                throw new InvalidOperationException("HTML output should not contain a ':root' selector when EnableCssCustomProperties is false.");
            }
        }
    }
}
